' ". . .the evening, the 2nd day begins. . .where (= i 1) => (= W 30). . .(. . .24(.00). . .<= W <=. . .48(.00). . .(100D))"
' " . . .the morning, the 2nd day begins. . .where (= i 1) => (= W 42). . ."


' ". . .the evening, the 3rd day begins. . .where (= i 2) => (= W 54). . .(. . .48(.00). . .<= W <=. . .72(.00). . .(100D))"
' " . . .the morning, the 3rd day begins. . .where (= i 2) => (= W 66). . ."


' ". . .the evening, the 4th day begins. . .where (= i 3) => (= W 78). . .(. . .72(.00). . .<= W <=. . .96(.00). . .(100D))"
' " . . .the morning, the 4th day begins. . .where (= i 3) => (= W 90). . ."


' ". . .the evening, the 5th day begins. . .where (= i 4) => (= W 102). . .(. . .96(.00). . .<= W <=. . .120(.00). . .(100D))"
' " . . .the morning, the 5th day begins. . .where (= i 4) => (= W 114). . ."


' ". . .the evening, the 6th day begins. . .where (= i 5) => (= W 126). . .(. . .120(.00). . .<= W <=. . .144(.00). . .(100D))"
' " . . .the morning, the 6th day begins. . .where (= i 5) => (= W 138). . ."


' ". . .the evening, the 7th day begins. . .where (= i 6) => (= W 150). . .(. . .144(.00). . .<= W <=. . .168(.00). . .(100D))"
' " . . .the morning, the 7th day begins. . .where (= i 6) => (= W 162). . ."



